st.assignment={title:passageTitle,text:st.testText,compare:false};st.groupFeedbackDraft='';st.optionalResource=0;st.committedGroups={...st.groups};st.groupGoalDraft=st.groupGoal;st.groupTaskDraft=st.groupTask;st.newResource={title:'',source:'',scope:'',desc:''};st.feedbackStore={김서윤:{...initialFeedback}};
function bindValue(path,value){const keys=path.split('.');let target=st;while(keys.length>1)target=target[keys.shift()];target[keys[0]]=value}
function loginAs(role){st.role=role;try{sessionStorage.setItem('lookteracy-demo-role',role)}catch{}route(role==='student'?'s-home':'t-dashboard')}
function submissionReview(){const missing=st.answers.findIndex(a=>!a.trim());if(missing!==-1){st.q=missing;st.mode='typing';render();toast('문항 '+(missing+1)+'의 답안을 작성해 주세요.');return}modal('최종 제출 전 확인',`${questions.map((q,i)=>`<div class="rubric"><h3>문항 ${i+1} · ${q.type}</h3><p>${esc(i===0?questions[0].choices[Number(st.answers[0])]:st.answers[i])}</p></div>`).join('')}<div class="actions">${button('돌아가서 수정','close','secondary')}${button('최종 제출','confirm-submit')}</div>`)}
function showSubmission(){modal('내 제출 답안',st.submitted?`${badge('제출 완료','green')}${questions.map((q,i)=>`<div class="rubric"><h3>문항 ${i+1}</h3><p>${esc(i===0?questions[0].choices[Number(st.answers[0])]:st.answers[i])}</p></div>`).join('')}${note('정답과 힌트는 이 화면에 제공하지 않습니다.')}`:'<p>아직 제출한 답안이 없어요.</p>')}
function showOptional(){const optional=st.optionalResource===1?{title:'숫자는 무엇을 설명하는가',text:'한 지역의 평균값은 그 안에 사는 사람들의 차이를 모두 보여주지 못한다. 평균 이용 시간이 짧아졌다고 해도 어떤 사람은 더 오래 기다릴 수 있다. 지표를 해석할 때는 누구의 경험이 포함되고 어떤 차이가 가려지는지 함께 살펴야 한다.',question:'평균값만으로 모든 사람의 상황을 판단하기 어려운 이유는 무엇일까요?'}:{title:'공공 도서관의 문턱',text:'도서관의 수가 늘어나는 것과 시민이 도서관을 편하게 이용하는 것은 같은 일이 아니다. 운영 시간, 교통편, 자료의 언어와 접근 가능한 시설이 갖추어져야 이용의 기회가 넓어진다.',question:'도서관 수만으로 이용 기회를 판단하기 어려운 이유는 무엇일까요?'};modal('선택형 추가 학습 · '+optional.title,`<div class="article" style="padding:0"><span class="pill">맥락·추론 연습</span><div class="divider"></div><div class="passage" style="font-size:18px"><p>${optional.text}</p></div><h3>${optional.question}</h3><label class="sr-only" for="optional-answer">추가 학습 답안</label><textarea id="optional-answer" data-bind="optionalAnswer" style="margin-top:15px" placeholder="자신의 생각을 적어보세요.">${esc(st.optionalAnswer)}</textarea><div class="actions">${button('힌트 보기','optional-hint','secondary')}${button('해설 확인·학습 마치기','optional-finish')}</div>${st.optionalHint?`<div class="note" style="margin-top:15px">${st.optionalResource===1?'평균이 서로 다른 개인의 상황을 모두 보여주는지 살펴보세요.':'공공 시설의 수와 실제 이용 기회를 구분하는 문장을 살펴보세요.'}</div>`:''}</div>`)}
function setFeedbackStudent(name){st.feedbackStudent=name;st.feedbackDraft={...(st.feedbackStore[name]??initialFeedback)}}
function studentDetail(name){const i=studentNames.indexOf(name),status=statusFor(i);if(status==='분석 완료'){st.reportStudent=name;st.reportFinal=false;route('t-report')}else if(name==='김서윤'&&st.submitted)showSubmission();else modal(name+' 학생 · '+status,`<p>${status==='준비 실패'?'카메라 권한 또는 환경 점검 단계에서 도움이 필요해요. 재점검·재보정 방법을 안내해 주세요.':status==='제출 완료'?'답안을 제출했고 분석을 기다리고 있어요.':status==='응시 중'?'지문 읽기와 문항 응답을 진행하고 있어요.':status==='준비 중'?'카메라 환경 점검과 시선 보정을 진행하고 있어요.':'아직 테스트를 시작하지 않았어요.'}</p>${note('학생의 얼굴 영상은 교사에게 보여 주지 않아요.')}<div class="actions">${button('확인','close','secondary')}</div>`)}
const action={
 'landing-start':()=>route('login-student'),
 'teacher-preview-access':()=>loginAs('teacher'),
 'face-help':()=>modal('페이스패스 로그인 도움',`<p>얼굴이 안내선 안에 들어오도록 화면을 바라봐 주세요. 조명이 밝은 곳에서 모자나 마스크로 얼굴을 가리지 않으면 더 쉽게 확인할 수 있어요.</p><p>처음 이용한다면 학급을 연결하고 페이스패스를 등록해 주세요. 계속해서 로그인이 어렵다면 담당 선생님에게 문의해 주세요.</p><div class="actions">${button('확인','close')}</div>`),
 close:()=>$('#modal').close(),
 pause:()=>{st.paused=!st.paused;const stage=$('.tracking-stage');stage.classList.toggle('paused',st.paused);$('[data-action="pause"]').textContent=st.paused?'재생':'움직임 멈추기'},
 'face-preview':()=>{st.faceScan=!st.faceScan;render()},
 'login-student':()=>loginAs('student'),'login-teacher':()=>loginAs('teacher'),
 logout:()=>{st.role=null;try{sessionStorage.removeItem('lookteracy-demo-role')}catch{}route('landing')},
 'teacher-help':()=>modal('교사 접속 안내','<p>교사도 페이스패스로 로그인해요. 처음이라면 가입하기에서 교사로 등록한 뒤 얼굴로 로그인해 주세요.</p>'),
 'signup-back':()=>{if(st.signup>0){st.signup--;render()}else route('login-student')},
 'signup-next':()=>{if(st.signup<2){st.signup++;render()}else{st.signup=0;st.faceScan=st.registered;route('login-student');toast('등록을 마쳤어요.')}},
 'register-face':()=>{st.registered=!st.registered;render()},
 'prep-check':()=>{stopCalibrationMotion();st.prep=1;st.cal=0;render()},
 'prep-error':()=>modal('점검이 완료되지 않았어요',`<p>카메라 권한, 조명, 얼굴 가림, 브라우저 환경을 차례로 확인해 보세요.</p><ul class="help-list"><li>기기에서 카메라 사용이 가능한지 확인하기</li><li>역광을 피하고 얼굴이 보이게 자세 조정하기</li><li>다시 점검해도 어렵다면 선생님에게 도움 요청하기</li></ul><div class="actions">${button('다시 점검','close')}</div>`),
 'cal-next':advanceCalibration,'cal-reset':()=>{stopCalibrationMotion();st.cal=0;render()},
 'font-plus':()=>{st.font=Math.min(26,st.font+1);document.documentElement.style.setProperty('--read-size',st.font+'px');$('.font-tool span').textContent=st.font+'px';toast('글자 크기를 바꿨다면 시선 보정을 다시 해 주세요.')},
 'font-minus':()=>{st.font=Math.max(18,st.font-1);document.documentElement.style.setProperty('--read-size',st.font+'px');$('.font-tool span').textContent=st.font+'px'},
 'read-done':()=>{st.readDone=true;st.q=0;route('s-answer')},
 'show-passage':()=>modal('지문 다시 보기',`<div class="article" style="padding:0"><h1>${passageTitle}</h1>${articleMeta()}${passageMarkup()}</div>`),
 'q-next':()=>{st.q=Math.min(2,st.q+1);st.ocr='';st.ocrConfirmed=false;render()},'q-prev':()=>{st.q=Math.max(0,st.q-1);st.ocr='';st.ocrConfirmed=false;render()},
 'ink-clear':()=>{st.ink[st.q]=[];st.ocr='';st.ocrConfirmed=false;render()},
 'ocr-example':()=>{st.ocr=st.q===1?'호랑이의 힘이 나쁜 기운을 막아 준다고 믿었지만, 무섭지 않게 곁에 두고 싶어서 눈을 크게, 발을 뭉툭하게 익살스럽게 그렸기 때문이다.':'자료를 가리키며 설명해 청중이 그림을 보며 이해하게 했고, 까치 속담을 물어 청중의 참여를 이끌었다.';st.ocrConfirmed=false;render();toast('변환한 문장을 확인하고 필요하면 고쳐 주세요.')},
 'ocr-apply':()=>{if(!st.ocrConfirmed){toast('인식 텍스트 확인 항목을 체크해 주세요.');return}if(!st.ocr.trim()){toast('적용할 텍스트를 입력해 주세요.');return}st.answers[st.q]=st.ocr.trim();st.mode='typing';render();toast('확인한 텍스트를 이번 문항의 답안에 적용했어요.')},
 'review-submit':submissionReview,'confirm-submit':()=>{st.submitted=true;route('s-complete')},'view-submission':showSubmission,
 'feedback-read':()=>{st.publishedRead=true;render();toast('게시된 교사 피드백을 확인했어요.')},
 'optional-start':el=>{st.optionalResource=Number(el.dataset.resource)||0;st.optionalHint=false;st.optionalAnswer='';st.optionalStarted=true;showOptional()},'optional-hint':()=>{st.optionalHint=true;showOptional()},
 'optional-finish':()=>{if(!st.optionalAnswer.trim()){toast('자신의 생각을 한 문장 이상 작성해 주세요.');return}st.optionalDone=true;modal('추가 학습 · 해설',`<span class="pill green">선택형 추가 학습 완료 상태</span><h3>${st.optionalResource===1?'평균 속에 가려진 차이를 살펴요.':'시설의 수와 이용 가능성을 구분해요.'}</h3><p>${st.optionalResource===1?'평균값은 집단의 전반적인 모습을 보여주지만, 개인 사이의 분포와 차이를 함께 설명하지는 못합니다. 누구의 상황을 놓칠 수 있는지 확인해야 해요.':'운영 시간, 교통편, 접근 가능한 시설 같은 조건이 달라지면 같은 수의 도서관이 있어도 이용 기회는 달라질 수 있어요.'}</p><div class="actions">${button('학습 마치기','close')}</div>`)},
 'quote-clear':()=>{const draft=$('#comment-text')?.value??'';st.quote=null;render();$('#comment-text').value=draft},
 'ai-question':()=>{st.aiQuestion=(st.aiQuestion+1)%3;const draft=$('#comment-text')?.value??'';render();if($('#comment-text'))$('#comment-text').value=draft},
 'group-submit':()=>{if(st.summary.trim().length<30){toast('함께 찾은 근거와 설명을 두 문장 정도로 작성해 주세요.');return}st.groupSubmitted=true;render();toast('공동 결과물을 제출했어요.')},
 'group-reopen':()=>{st.groupSubmitted=false;render()},
 'past-city-test':()=>modal('지난 테스트 · 도시의 녹지는 누구를 위한 것인가',`<p>2회차 · 11월 11일 제출 완료</p><div class="rubric"><h3>선생님의 피드백</h3><p>${esc(initialFeedback.strength)}</p></div><div class="actions">${button('확인','close','secondary')}</div>`),
 'past-test':()=>modal('지난 테스트 · 2회차',`<p>정보의 신뢰성을 판단하는 기준 · 11월 11일 제출 완료</p><div class="rubric"><h3>지난 교사 피드백</h3><p>정보의 출처와 근거를 구분했어요. 다음에는 서로 다른 자료가 같은 주장을 뒷받침하는지 확인해 보세요.</p></div><div class="actions">${button('확인','close','secondary')}</div>`),
 'past-group':()=>modal('지난 모둠 결과물',`<span class="pill gray">1회차</span><h3>서로 다른 근거를 비교하며 읽기</h3><p>우리 모둠은 두 자료의 출처와 설명 범위를 비교했습니다. 같은 결론이라도 어떤 근거에서 출발했는지 확인해야 한다고 정리했습니다.</p><div class="rubric"><h3>교사 피드백</h3><p>근거의 출처와 설명 범위를 함께 확인한 점이 좋습니다.</p></div>`),
 'face-help':()=>modal('페이스패스 안내',`<p>최초 등록한 인증 정보로 학생 계정을 확인하는 과정이에요. 등록·인증 상태와 시선 보정 상태는 따로 관리해요.</p>${note('얼굴 사진은 저장하지 않고, 얼굴 특징값만 이 기기에 저장해요.')}`),
 'builder-next':()=>{st.builderTab=st.builderTab==='passage'?'questions':'assign';render()},
 'question-info':el=>{const i=Number(el.dataset.question);modal('문항 '+(i+1)+' · 정답·해설',`<h3>${questions[i].text}</h3><p>${i===0?'정답: 선택지 2. 호랑이는 공포의 대상이었지만 액운을 막는 수호자로 받아들여졌고 익살스럽게 그려져 친근한 존재가 되었으며, 까치는 기쁜 소식을 전하는 길조라고 설명합니다.':i===1?'평가 기준: 호랑이의 힘이 나쁜 기운을 막아 준다는 믿음(수호자)과 익살스러운 표현(큰 눈, 뭉툭한 발)으로 친근하게 곁에 두고 싶었던 심리를 연결해 설명했는지 확인합니다.':'평가 기준: 자료 제시·가리키기, 청중에게 질문하기, 속담 활용, 몸짓, 지시 표현(㉠, ㉢)과 화제 전환 표지(㉡) 가운데 두 가지를 찾고, 청중의 이해와 참여에 주는 효과를 설명했는지 확인합니다.'}</p>${note('서술형은 단일 문장과의 일치가 아닌 교사가 확정한 루브릭에 따라 검토해야 합니다.')}`)},
 'test-preview':()=>modal('학생 화면 미리보기',`<div class="article" style="padding:0"><span class="pill">당일 지문 · 편집 중</span><h1>${esc(st.testTitle)}</h1><div class="passage" style="font-size:17px">${esc(st.testText).split('\n').filter(Boolean).map(p=>`<p>${p}</p>`).join('')}</div>${st.compare?'<div class="note">비교 지문: 공공 도서관의 문턱 · 함께 배정</div>':''}</div><div class="divider"></div><p>선택형 1개 · 서술형 2개. 학생 화면에는 정답·루브릭을 표시하지 않습니다.</p>`),
 'assign-test':()=>{if(!$('#assign-review').checked){toast('지문·문항·대상 학급 검토 항목을 확인해 주세요.');return}if(!st.testTitle.trim()||!st.testText.trim()){toast('테스트 제목과 지문을 입력해 주세요.');return}st.assigned=true;st.assignment={title:st.testTitle,text:st.testText,compare:st.compare};render();toast('테스트를 배정했어요.')},
 'student-detail':el=>studentDetail(el.dataset.person),
 'report-final':()=>{st.reportFinal=true;render();toast('리포트 검토를 완료했어요. 이미지로 내려받을 수 있어요.')},
 'report-export':exportReport,
 'feedback-evidence':()=>{st.reportStudent=st.feedbackStudent;route('t-report')},
 'feedback-generate':()=>{st.feedbackDraft={...initialFeedback};render();toast('분석 초안을 불러왔어요. 검토 후 게시해 주세요.')},
 'feedback-review':()=>{if(Object.values(st.feedbackDraft).some(v=>!v.trim())){toast('강점·보완 개념·읽기 전략을 모두 작성해 주세요.');return}modal('학생에게 게시할 내용 확인',`<p>${esc(st.feedbackStudent)} 학생에게 다음 피드백을 게시합니다.</p>${Object.entries(st.feedbackDraft).map(([k,v])=>`<div class="rubric"><h3>${({strength:'강점',concept:'보완할 개념',strategy:'다음 읽기 전략'})[k]}</h3><p>${esc(v)}</p></div>`).join('')}<div class="actions">${button('다시 수정','close','secondary')}${button('검토 완료 · 게시','feedback-publish')}</div>`)},
 'feedback-publish':()=>{st.feedbackStore[st.feedbackStudent]={...st.feedbackDraft};if(st.feedbackStudent==='김서윤'){st.published={...st.feedbackDraft};st.publishedPassageTitle=passageTitle;st.feedbackVersion++;st.publishedRead=false}$('#modal').close();toast('피드백을 게시했어요. 학생 화면에 반영됩니다.');render()},
 'groups-confirm':()=>{const n=[0,1].map(g=>Object.values(st.groups).filter(x=>x===g).length);if(n.some(x=>x===0)){toast('비어 있는 모둠이 있습니다. 구성원을 조정해 주세요.');return}st.groupsConfirmed=true;st.committedGroups={...st.groups};render();toast('모둠 구성을 확정했어요.')},
 'group-assign':()=>{if(!st.groupsConfirmed){toast('모둠 구성 변경을 먼저 확정해 주세요.');return}if(!st.groupGoalDraft.trim()||!st.groupTaskDraft.trim()){toast('활동 목표와 과제를 입력해 주세요.');return}st.groupGoal=st.groupGoalDraft;st.groupTask=st.groupTaskDraft;st.groupAssigned=true;render();toast('모둠 목표와 과제를 반영했어요.')},
 'group-feedback':()=>{if(!st.groupFeedbackDraft.trim()){toast('모둠에 전할 피드백을 입력해 주세요.');return}st.teacherGroupFeedback=st.groupFeedbackDraft;toast('모둠 피드백을 학생 화면에 반영했어요.')},
 'resource-view':el=>{const r=[...resources,...st.extraResources].find(x=>x.title===el.dataset.resourceTitle);modal(esc(r.title),`<span class="pill">${esc(r.tag)}</span><h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p><div class="source-box">${esc(r.source??'출처: LOOKteracy 자체 제작')}<br>${esc(r.scope??'사용 범위: 수업 활용')}</div>${r.type==='rubrics'?domains.map(d=>`<div class="rubric"><h3>${d}</h3><p>관찰 근거·확인할 질문·지도 방향을 구분해 기록합니다.</p></div>`).join(''):r.title===passageTitle?`<div class="passage" style="font-size:17px">${paras.map(p=>`<p>${p.join(' ')}</p>`).join('')}</div>`:''}<div class="actions">${button('자료 수정','resource-edit','secondary',`data-resource-title="${esc(r.title)}"`)}</div>`)},
 'resource-use':el=>{const r=[...resources,...st.extraResources].find(x=>x.title===el.dataset.resourceTitle);if(r.type==='passages'){if(r.title==='공공 도서관의 문턱')st.compare=true;else st.testTitle=r.title;st.builderTab='passage'}else st.builderTab='questions';route('t-builder');toast('선택한 자료를 테스트 구성에서 검토하세요.')},
 'resource-add':()=>modal('자료 등록',`${field('자료 제목','newResource.title',st.newResource.title)}${field('출처','newResource.source',st.newResource.source,'text','작성자·자료의 출처')}${field('사용 범위','newResource.scope',st.newResource.scope,'text','저작권·수업 활용 가능 범위')}${textfield('내용·설명','newResource.desc',st.newResource.desc)}<p class="small">현재 자료실 탭에 추가됩니다.</p><div class="actions">${button('등록하기','resource-save')}</div>`),
 'resource-save':()=>{const r=st.newResource;if(!r.title.trim()||!r.source.trim()||!r.scope.trim()){toast('제목·출처·사용 범위를 입력해 주세요.');return}st.extraResources.push({...r,type:st.resourceTab,tag:'교사 등록 자료'});st.newResource={title:'',source:'',scope:'',desc:''};$('#modal').close();render();toast('자료실에 추가했어요.')},
 'class-connect':()=>modal('학급 연결 안내',`<span class="pill">인하고등학교 · 1학년 2반</span><h3>학급 연결 코드 · LOOK-102</h3><p>학생이 처음 가입할 때 이 코드로 학급을 확인해요.</p>${note('담당 학급 외 자료는 제공하지 않습니다. 학생 상세 리포트와 시선 기록은 교사 공간에서만 표시합니다.')}`),
 help:()=>modal('LOOKteracy 이용 안내',`<p>학생은 배정된 지문을 읽고 답하며, 교사는 읽기 리포트와 피드백으로 다음 수업을 준비해요.</p><ul class="help-list"><li>학생과 교사는 각자 페이스패스로 로그인합니다.</li><li>다른 계정으로 들어가려면 로그아웃 후 다시 로그인합니다.</li><li>학생: 준비·보정 → 지문 읽기 → 선택·타이핑·필기/OCR → 제출</li><li>교사: 테스트 배정 → 현황·리포트 검토 → 피드백 게시·모둠 운영</li><li>서술형 답안은 타이핑하거나 필기로 쓸 수 있습니다.</li><li>교사 리포트는 검토 완료로 표시한 뒤 PNG 이미지로 받을 수 있습니다.</li></ul>`)
};
function setupInk(){const canvas=$('#ink');if(!canvas)return;const box=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=Math.round(box.width*ratio);canvas.height=Math.round(box.height*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.lineWidth=2.3;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#426f90';const redraw=()=>{ctx.clearRect(0,0,box.width,box.height);for(const stroke of st.ink[st.q]){ctx.beginPath();stroke.forEach((p,i)=>i?ctx.lineTo(p.x*box.width,p.y*box.height):ctx.moveTo(p.x*box.width,p.y*box.height));ctx.stroke()}};redraw();let drawing=false;const pos=e=>{const b=canvas.getBoundingClientRect();return{x:(e.clientX-b.left)/b.width,y:(e.clientY-b.top)/b.height}};canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);st.ink[st.q].push([pos(e)]);e.preventDefault()});canvas.addEventListener('pointermove',e=>{if(!drawing)return;st.ink[st.q].at(-1).push(pos(e));redraw();e.preventDefault()});for(const type of ['pointerup','pointercancel'])canvas.addEventListener(type,()=>{drawing=false})}
async function exportReport(){if(!st.reportFinal){toast('교사 검토 완료로 표시한 뒤 출력하세요.');return}await document.fonts.ready;const c=document.createElement('canvas');c.width=1200;c.height=4600;const ctx=c.getContext('2d');ctx.fillStyle='#f3f7fb';ctx.fillRect(0,0,c.width,c.height);let y=65;const text=(s,size=22,color='#526d81',bold=false)=>{ctx.font=`${bold?'600':'400'} ${size}px 'Noto Sans KR', sans-serif`;ctx.fillStyle=color;let line='';for(const char of s){if(ctx.measureText(line+char).width>1050||char==='\n'){ctx.fillText(line,75,y);y+=size*1.8;line=char==='\n'?'':char}else line+=char}if(line){ctx.fillText(line,75,y);y+=size*1.8}};text('LOOKteracy · 학생 읽기 과정 리포트',34,'#2f536d',true);y+=12;text(`${st.reportStudent} · 인하고등학교 ${st.className} · ${st.round}`,20);text('교사 검토 완료',18,'#829eaf');y+=30;text(passageTitle,27,'#3d6580',true);text('3문단 · 호랑이를 익살스럽게 그린 까닭',18,'#8aa3b3');y+=18;ctx.font="400 25px 'Noto Sans KR', sans-serif";const segments=[['그런데 이 그림 속 호랑이, 수호자처럼 보이시나요? 어딘지 ',null],['의연하고 듬직한','#ded3c0'],[' 모습은 아닙니다. 눈은 이렇게 ',null],['과장되게 크고','#c7deed'],[', 발도 뭉툭하지요. 이는 호랑이를 ',null],['익살스럽게 그림으로써 친근한 존재로','#d4dbc8'],[' 곁에 두고 싶어 했던 심리가 반영된 것입니다.',null]];let measureX=75,lines=1;for(const [str]of segments)for(const ch of str){const w=ctx.measureText(ch).width;if(measureX+w>1125){lines++;measureX=75}measureX+=w}ctx.fillStyle='#fff';ctx.fillRect(60,y-35,1080,lines*45+30);let rx=75;for(const [str,bg]of segments){for(const ch of str){const w=ctx.measureText(ch).width;if(rx+w>1125){rx=75;y+=45}if(bg){ctx.fillStyle=bg;ctx.fillRect(rx-1,y-26,w+2,36)}ctx.fillStyle='#526d81';ctx.fillText(ch,rx,y);rx+=w}}y+=90;text('범례 · 응시 시간 짧음 → 김',18,'#829eaf');const grad=ctx.createLinearGradient(75,0,600,0);grad.addColorStop(0,'#d6e7f2');grad.addColorStop(.35,'#afc8cc');grad.addColorStop(.7,'#c1c7ad');grad.addColorStop(1,'#cbb28d');ctx.fillStyle=grad;ctx.fillRect(75,y,525,12);y+=55;text('독해 속도 520 글자/분 · 시선 고정 시간 292ms · 시폭 7.9글자',18);y+=28;for(const [domain,obs,interpret,guide]of observations){ctx.strokeStyle='#dce7ef';ctx.beginPath();ctx.moveTo(75,y);ctx.lineTo(1125,y);ctx.stroke();y+=43;text(domain,26,'#436d8b',true);text('관찰: '+obs,21);text('해석 후보·확인 필요: '+interpret,21);text('지도 제안: '+guide,21);y+=27}text('출처: 26년 고1 3월 모의고사 (1~3) 지문',17,'#91a6b4');text('출력 이미지도 개인 리포트 접근 범위에 포함됩니다.',17,'#91a6b4');const out=document.createElement('canvas');out.width=1200;out.height=Math.ceil(y+35);out.getContext('2d').drawImage(c,0,0);const blob=await new Promise(res=>out.toBlob(res,'image/png'));const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`LOOKteracy_${st.reportStudent}_3회차_리포트.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('검토한 리포트를 PNG로 내려받았어요.')}
const originalResourceAdd=action['resource-add'], originalResourceSave=action['resource-save'];
action['resource-add']=el=>{if(el){st.editResource=null;st.newResource={title:'',source:'',scope:'',desc:''}}originalResourceAdd()};
action['resource-edit']=el=>{const r=[...resources,...st.extraResources].find(x=>x.title===el.dataset.resourceTitle);st.editResource=r;st.newResource={title:r.title,source:r.source??'LOOKteracy 자체 제작',scope:r.scope??'수업 활용',desc:r.desc};originalResourceAdd();$('#modal-title').textContent='자료 수정';$('#modal [data-action="resource-save"]').textContent='수정 저장';$('#modal .modal-body>p').textContent='수정한 내용은 자료실에 바로 반영됩니다.'};
action['resource-save']=()=>{if(!st.editResource){originalResourceSave();return}if(!st.newResource.title.trim()||!st.newResource.source.trim()||!st.newResource.scope.trim()){toast('제목·출처·사용 범위를 입력해 주세요.');return}Object.assign(st.editResource,st.newResource);st.editResource=null;$('#modal').close();render();toast('자료 수정 내용을 반영했어요.')};
document.addEventListener('click',async e=>{const skip=e.target.closest('.skip');if(skip){e.preventDefault();$('#main').focus();return}const r=e.target.closest('[data-route]');if(r){e.preventDefault();if(r.dataset.route==='t-feedback')setFeedbackStudent(st.reportStudent);route(r.dataset.route);return}const a=e.target.closest('[data-action]');if(a){e.preventDefault();try{await action[a.dataset.action]?.(a)}catch(err){console.error(err);toast('화면 동작을 완료하지 못했어요. 다시 확인해 주세요.')}return}const t=e.target.closest('[data-tab]');if(t){if(t.dataset.tab==='group')st.tab=t.dataset.value;if(t.dataset.tab==='builder')st.builderTab=t.dataset.value;if(t.dataset.tab==='report')st.reportTab=t.dataset.value;if(t.dataset.tab==='library')st.resourceTab=t.dataset.value;const key=t.dataset.tab,value=t.dataset.value;render();document.querySelector(`[data-tab="${key}"][data-value="${value}"]`)?.focus({preventScroll:true});return}const q=e.target.closest('[data-q]');if(q){st.q=Number(q.dataset.q);st.ocr='';st.ocrConfirmed=false;render();return}const m=e.target.closest('[data-mode]');if(m){st.mode=m.dataset.mode;render();return}const s=e.target.closest('[data-sentence]');if(s){const draft=$('#comment-text')?.value??'';st.tab='talk';st.quote=st.quote===Number(s.dataset.sentence)?null:Number(s.dataset.sentence);render();$('#comment-text').value=draft;$('#comment-text').focus({preventScroll:innerWidth>800});return}const f=e.target.closest('[data-filter]');if(f){st.filter=f.dataset.filter;render();return}});
document.addEventListener('input',e=>{if(e.target.dataset.bind)bindValue(e.target.dataset.bind,e.target.value);if(e.target.dataset.answer){st.answers[Number(e.target.dataset.answer)]=e.target.value;const n=$('.answer-foot .small');if(n)n.textContent=st.answers.filter(x=>x.trim()).length+' / 3문항 작성'}if(e.target.id==='student-search'){st.search=e.target.value;const pos=e.target.selectionStart;const tmp=document.createElement('div');tmp.innerHTML=studentTable(st.page==='t-class'?'class':'monitor');$('#student-rows').innerHTML=tmp.querySelector('#student-rows').innerHTML;$('#row-count').textContent=tmp.querySelector('#row-count').textContent}if(e.target.id==='resource-search'){st.resourceSearch=e.target.value;const tmp=document.createElement('div');tmp.innerHTML=views['t-library']();$('#resource-list').innerHTML=tmp.querySelector('#resource-list').innerHTML}});
document.addEventListener('change',e=>{if(e.target.name==='mc-answer'){st.answers[0]=e.target.value;render()}if(e.target.id==='ocr-confirm')st.ocrConfirmed=e.target.checked;if(e.target.id==='compare-check')st.compare=e.target.checked;if(e.target.id==='font-select'){st.font=Number(e.target.value);document.documentElement.style.setProperty('--read-size',st.font+'px');toast('지문 글자 크기를 '+st.font+'px로 바꿨어요.')}if(e.target.id==='report-select'){st.reportStudent=e.target.value;st.reportFinal=false;render()}if(e.target.id==='feedback-select'){setFeedbackStudent(e.target.value);render()}if(e.target.dataset.move){st.groups[e.target.dataset.move]=Number(e.target.value);st.groupsConfirmed=false;render()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='comment-form'){const text=$('#comment-text').value.trim();if(!text)return;st.comments.push({name:'김서윤',text,quote:st.quote});st.quote=null;render();const node=$('.discussion-body');node.scrollTop=node.scrollHeight;toast('모둠 활동에 의견을 추가했어요.')}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-sentence]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click()}if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const all=[...e.target.parentElement.querySelectorAll('[role="tab"]')],index=all.indexOf(e.target);all[e.key==='Home'?0:e.key==='End'?all.length-1:(index+(e.key==='ArrowRight'?1:all.length-1))%all.length].click()}});
function historyNavigation(){const p=location.hash.slice(1)||'landing';route(p,true);if(st.page==='t-group-detail'&&!activeCoopRecord().ai)startCoopAnalysis(st.coopTestId)}
window.addEventListener('popstate',historyNavigation);window.addEventListener('hashchange',historyNavigation);
const dialog=$('#modal');dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});
installCooperationActions();
historyNavigation();
